transfer.example:
let source = label("inputs")
let destination = label("assembly")
transfer(source, destination, item("minecraft:iron_ingot"), 16) into result
print(result.moved, result.remaining, result.status)

wait.example:
integer later(integer value) {
  wait(20);
  return value + 1;
}
every 40 ticks {
  let next = later(3);
  print(next);
}
